@@ -0,0 +1,150 @@
+package provider
+
+import (
+	"encoding/json"
+	"path/filepath"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/yetone/magpie/internal/testenv"
+)
+
+// Sanitized quotas.json entry. spans and windows have matching indexes.
+const cursorAsideSnapshot = `{
+  "at":"2026-10-31T16:51:12Z",
+  "quota":{
+    "provider":"cursor","name":"Cursor","user":"cursor-account-1",
+    "windows":[
+      {"name":"Weekly","used":56.1,"resetsAt":"2026-11-04T02:14:01.555Z"},
+      {"name":"Grok Bot","used":56.1,"resetsAt":"2026-11-04T02:14:01.555Z"},
+      {"name":"On-demand","used":0,"resetsAt":"2026-11-04T02:14:01.555Z","display":"$0.00","text":true}
+    ],
+    "readAt":"2026-10-31T16:51:12Z"
+  },
+  "spans":[{"span":604800000000000,"aside":true},{"span":604800000000000,"aside":true},{"aside":true}]
+}`
+
+func cursorAsideFixture(t *testing.T) (SubscriptionQuota, time.Time) {
+	t.Helper()
+	testenv.SetHome(t, t.TempDir())
+	root := t.TempDir()
+	t.Setenv("XDG_CONFIG_HOME", root)
+	// Fail before any history I/O if portable mode overrides the test home.
+	rel, err := filepath.Rel(root, quotaHistPath())
+	if err != nil || filepath.IsAbs(rel) || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
+		t.Fatalf("history path escapes temporary config: %s", quotaHistPath())
+	}
+	var e lastQuota
+	if err := json.Unmarshal([]byte(cursorAsideSnapshot), &e); err != nil {
+		t.Fatal(err)
+	}
+	if len(e.Spans) != len(e.Q.Windows) || e.Q.ReadAt == nil {
+		t.Fatal("invalid fixture")
+	}
+	// Apply quota_last.go's sidecars without reported(): reported() sets
+	// AsOf on an old cached read, which would mask the aside rejection.
+	for i := range e.Q.Windows {
+		e.Q.Windows[i].Span = e.Spans[i].Span
+		e.Q.Windows[i].Model = e.Spans[i].Model
+		e.Q.Windows[i].Aside = e.Spans[i].Aside
+	}
+	return e.Q, e.Q.ReadAt.Add(time.Second)
+}
+
+// Measured windows keep history independently of their routing Aside flag.
+func TestCursorAsideHistoryRecords(t *testing.T) {
+	for _, tc := range []struct {
+		name string
+		used float64
+		left float64
+	}{{"snapshot_exact", 56.1, 43.90}, {"minimal_used_56", 56, 44}} {
+		t.Run(tc.name, func(t *testing.T) {
+			q, now := cursorAsideFixture(t)
+			q.Windows[0].Used, q.Windows[1].Used = tc.used, tc.used
+			if q.Error != "" || q.AsOf != nil {
+				t.Fatal("fixture must be a fresh successful read")
+			}
+			for _, w := range q.Windows {
+				if w.PoolWindow() {
+					t.Fatal("fixture must not be a pool")
+				}
+				p, ok := pointOf(w, *q.ReadAt, now)
+				if w.Text {
+					if ok {
+						t.Fatalf("%s text unexpectedly produced a point", w.Name)
+					}
+				} else if !ok || p.Left != tc.left {
+					t.Fatalf("%s: point = %+v, accepted=%v, want %v%% left", w.Name, p, ok, tc.left)
+				}
+			}
+			// Start with the single historical Weekly point observed locally.
+			oldAt, _ := time.Parse(time.RFC3339, "2026-10-31T08:51:41Z")
+			key := quotaHistKey(q.Provider, q.User)
+			writeQuotaHist(quotaHist{key: map[string][]QuotaPoint{"Weekly": {{At: oldAt, Left: 51.98}}}})
+			noteQuotaHistory([]SubscriptionQuota{q}, now)
+			ws := readQuotaHist()[key]
+			if pts := ws["Weekly"]; len(pts) != 2 || !pts[0].At.Equal(oldAt) || pts[0].Left != 51.98 || pts[1].Left != tc.left {
+				t.Fatalf("Weekly history must keep the old point and append the reading: %+v", pts)
+			}
+			if pts := ws["Grok Bot"]; len(pts) != 1 || pts[0].Left != tc.left {
+				t.Fatalf("Grok Bot history: %+v", pts)
+			}
+			if len(ws["On-demand"]) != 0 {
+				t.Fatal("text-only On-demand must not become a fictitious 100% point")
+			}
+			t.Logf("used=%v: Weekly and Grok Bot recorded %v%% left; old Weekly point retained; text excluded", tc.used, tc.left)
+		})
+	}
+	t.Run("text_without_aside_control", func(t *testing.T) {
+		q, now := cursorAsideFixture(t)
+		q.Windows = q.Windows[2:]
+		q.Windows[0].Aside = false
+		if _, ok := pointOf(q.Windows[0], *q.ReadAt, now); ok {
+			t.Fatal("text-only window without Aside unexpectedly produced a point")
+		}
+		noteQuotaHistory([]SubscriptionQuota{q}, now)
+		if len(readQuotaHist()) != 0 {
+			t.Fatal("text-only window without Aside unexpectedly wrote history")
+		}
+	})
+	t.Run("aside_false_control", func(t *testing.T) {
+		q, now := cursorAsideFixture(t)
+		q.Windows[0].Aside = false // Control only; never change live routing.
+		p, ok := pointOf(q.Windows[0], *q.ReadAt, now)
+		if !ok || p.Left != 43.90 {
+			t.Fatalf("control point = %+v, accepted=%v", p, ok)
+		}
+		noteQuotaHistory([]SubscriptionQuota{q}, now)
+		pts := readQuotaHist()[quotaHistKey(q.Provider, q.User)]["Weekly"]
+		if len(pts) != 1 || pts[0].Left != 43.90 {
+			t.Fatalf("control did not persist 43.90%%: %+v", pts)
+		}
+	})
+	t.Run("codex_control", func(t *testing.T) {
+		q, now := cursorAsideFixture(t)
+		q.Provider, q.User = "codex", "codex-account-1"
+		q.Windows = []QuotaWindow{{Name: "5 hours", Used: 65}, {Name: "7 days", Used: 39}}
+		noteQuotaHistory([]SubscriptionQuota{q}, now)
+		ws := readQuotaHist()[quotaHistKey(q.Provider, q.User)]
+		if len(ws["5 hours"]) != 1 || ws["5 hours"][0].Left != 35 || len(ws["7 days"]) != 1 || ws["7 days"][0].Left != 61 {
+			t.Fatalf("Codex control: %+v", ws)
+		}
+	})
+}
+
+// This regression test should FAIL before a fix and PASS after it.
+func TestCursorAsideHistoryExpected(t *testing.T) {
+	q, now := cursorAsideFixture(t)
+	noteQuotaHistory([]SubscriptionQuota{q}, now)
+	ws := readQuotaHist()[quotaHistKey(q.Provider, q.User)]
+	for _, name := range []string{"Weekly", "Grok Bot"} {
+		pts := ws[name]
+		if len(pts) != 1 || pts[0].Left != 43.90 {
+			t.Errorf("%s: want one measured 43.90%% point despite routing Aside; got %+v", name, pts)
+		}
+	}
+	if len(ws["On-demand"]) != 0 {
+		t.Error("text-only On-demand must not become a fictitious 100% point")
+	}
+}
```
